"""幂等用例：同一租户内同一请求标识只产生一次业务效果。

并发语义依赖 SQLite 的 BEGIN IMMEDIATE：同一时刻只有一个请求能进入写事务，
后来的同标识请求在锁释放后读到的必然是已提交的首次记录，从而回放首次结果。
"""
import hashlib
import json
import sqlite3

from app.store import idempotency, orders
from app.store.db import connect

SCOPE_ORDER_CREATE = "order_create"
SCOPE_PAYMENT = "payment"
SCOPE_REVERSAL = "reversal"
SCOPE_RECONCILIATION = "reconciliation"
SCOPE_CORRECTION = "order_correction"


class IdempotentConflict(Exception):
    """同一请求标识对应了与首次不同的业务内容，或被用于不同类型的操作。"""


class IdemResult:
    def __init__(self, status_code: int, body: dict, replay: bool):
        self.status_code = status_code
        self.body = body
        self.replay = replay


def _fingerprint(parts: tuple) -> str:
    raw = json.dumps(parts, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def _finish(conn: sqlite3.Connection) -> None:
    conn.execute("COMMIT")


def _abort(conn: sqlite3.Connection) -> None:
    conn.execute("ROLLBACK")


def accept_order(tenant: str, request_id: str, order_id: str, amount_cents: int, currency: str) -> IdemResult:
    request_hash = _fingerprint((SCOPE_ORDER_CREATE, order_id, amount_cents, currency))
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = idempotency.get_conn(conn, tenant, request_id)
        if existing is not None:
            _finish(conn)
            if existing["scope"] != SCOPE_ORDER_CREATE or existing["request_hash"] != request_hash:
                raise IdempotentConflict("request id was already used with different request content")
            return IdemResult(existing["status_code"], json.loads(existing["response_json"]), replay=True)

        try:
            try:
                orders.insert_conn(conn, tenant, order_id, amount_cents, currency)
                status_code, body = 201, orders.get_conn(conn, tenant, order_id)
            except sqlite3.IntegrityError:
                # 同一租户重复受理（未携带本请求标识的既有订单/或首次结果即冲突）
                status_code, body = 409, {"detail": "order already accepted"}
            idempotency.insert_conn(
                conn, tenant, request_id, SCOPE_ORDER_CREATE, request_hash, order_id,
                status_code, json.dumps(body, ensure_ascii=False),
            )
            _finish(conn)
        except Exception:
            _abort(conn)
            raise
    finally:
        conn.close()
    return IdemResult(status_code, body, replay=False)


def register_payment(tenant: str, request_id: str, order_id: str, amount_cents: int) -> IdemResult:
    request_hash = _fingerprint((SCOPE_PAYMENT, order_id, amount_cents))
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = idempotency.get_conn(conn, tenant, request_id)
        if existing is not None:
            _finish(conn)
            if existing["scope"] != SCOPE_PAYMENT or existing["request_hash"] != request_hash:
                raise IdempotentConflict("request id was already used with different request content")
            return IdemResult(existing["status_code"], json.loads(existing["response_json"]), replay=True)

        try:
            try:
                body = orders.pay_conn(conn, tenant, order_id, amount_cents, request_id)
                status_code = 200
            except LookupError:
                status_code, body = 404, {"detail": "order not found"}
            except ValueError as error:
                status_code, body = 409, {"detail": str(error)}
            idempotency.insert_conn(
                conn, tenant, request_id, SCOPE_PAYMENT, request_hash, order_id,
                status_code, json.dumps(body, ensure_ascii=False),
            )
            _finish(conn)
        except Exception:
            _abort(conn)
            raise
    finally:
        conn.close()
    return IdemResult(status_code, body, replay=False)


def reverse_payment(tenant: str, request_id: str, order_id: str, amount_cents: int) -> IdemResult:
    request_hash = _fingerprint((SCOPE_REVERSAL, order_id, amount_cents))
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = idempotency.get_conn(conn, tenant, request_id)
        if existing is not None:
            _finish(conn)
            if existing["scope"] != SCOPE_REVERSAL or existing["request_hash"] != request_hash:
                raise IdempotentConflict("request id was already used with different request content")
            return IdemResult(existing["status_code"], json.loads(existing["response_json"]), replay=True)

        try:
            try:
                body = orders.reverse_conn(conn, tenant, order_id, amount_cents, request_id)
                status_code = 200
            except LookupError:
                status_code, body = 404, {"detail": "order not found"}
            except ValueError as error:
                status_code, body = 409, {"detail": str(error)}
            idempotency.insert_conn(
                conn, tenant, request_id, SCOPE_REVERSAL, request_hash, order_id,
                status_code, json.dumps(body, ensure_ascii=False),
            )
            _finish(conn)
        except Exception:
            _abort(conn)
            raise
    finally:
        conn.close()
    return IdemResult(status_code, body, replay=False)


def reconcile_order(tenant: str, request_id: str, order_id: str, amount_cents: int) -> IdemResult:
    request_hash = _fingerprint((SCOPE_RECONCILIATION, order_id, amount_cents))
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = idempotency.get_conn(conn, tenant, request_id)
        if existing is not None:
            _finish(conn)
            if existing["scope"] != SCOPE_RECONCILIATION or existing["request_hash"] != request_hash:
                raise IdempotentConflict("request id was already used with different request content")
            return IdemResult(existing["status_code"], json.loads(existing["response_json"]), replay=True)

        try:
            try:
                body = orders.reconcile_conn(conn, tenant, order_id, amount_cents, request_id)
                status_code = 200
            except LookupError:
                status_code, body = 404, {"detail": "order not found"}
            except ValueError as error:
                status_code, body = 409, {"detail": str(error)}
            idempotency.insert_conn(
                conn, tenant, request_id, SCOPE_RECONCILIATION, request_hash, order_id,
                status_code, json.dumps(body, ensure_ascii=False),
            )
            _finish(conn)
        except Exception:
            _abort(conn)
            raise
    finally:
        conn.close()
    return IdemResult(status_code, body, replay=False)


def correct_order(
    tenant: str,
    request_id: str,
    order_id: str,
    new_order_id: str,
    new_amount_cents: int,
    new_currency: str,
) -> IdemResult:
    request_hash = _fingerprint((SCOPE_CORRECTION, order_id, new_order_id, new_amount_cents, new_currency))
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = idempotency.get_conn(conn, tenant, request_id)
        if existing is not None:
            _finish(conn)
            if existing["scope"] != SCOPE_CORRECTION or existing["request_hash"] != request_hash:
                raise IdempotentConflict("request id was already used with different request content")
            return IdemResult(existing["status_code"], json.loads(existing["response_json"]), replay=True)

        try:
            try:
                body = orders.correct_conn(
                    conn, tenant, order_id, new_order_id, new_amount_cents, new_currency, request_id
                )
                status_code = 200
            except LookupError:
                status_code, body = 404, {"detail": "order not found"}
            except ValueError as error:
                # 含 CorrectionRejected：业务拒绝结论已随更正留痕落库，此处只固化响应
                status_code, body = 409, {"detail": str(error)}
            idempotency.insert_conn(
                conn, tenant, request_id, SCOPE_CORRECTION, request_hash, order_id,
                status_code, json.dumps(body, ensure_ascii=False),
            )
            _finish(conn)
        except Exception:
            _abort(conn)
            raise
    finally:
        conn.close()
    return IdemResult(status_code, body, replay=False)

import argparse

from fastapi import Body, FastAPI, Header, HTTPException
from pydantic import BaseModel, Field

from app.rules import order_rules
from app.store import orders
from app.store.db import connect, migrate
from app.usecase import batch as batch_uc
from app.usecase import orders as orders_uc

app = FastAPI(title="settlement-ledger")

IDEMPOTENCY_HEADER = "Idempotency-Key"

class OrderIn(BaseModel):
    tenant: str = Field(min_length=1)
    order_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)
    currency: str = Field(min_length=3, max_length=3)

class PaymentIn(BaseModel):
    amount_cents: int = Field(gt=0)

class ReversalIn(BaseModel):
    # 不使用 gt=0：金额 <= 0 属于业务非法，需与「超过已收」一起由业务层
    # 返回 409 及明确原因，与订单不存在(404)、幂等冲突(422) 区分开。
    amount_cents: int

class ReconcileIn(BaseModel):
    # 同 ReversalIn：金额 <= 0 由业务层返回 409 及明确原因
    amount_cents: int

class CorrectionIn(BaseModel):
    # 不使用 pydantic 约束：金额 <= 0、标识为空、币种不受支持都属于业务非法，
    # 需由业务层返回 409 及明确原因，与订单不存在(404)、幂等冲突(422) 区分开。
    order_id: str
    amount_cents: int
    currency: str

@app.get("/health")
def health() -> dict:
    conn = connect()
    try:
        conn.execute("SELECT 1")
    finally:
        conn.close()
    return {"status": "ok"}

@app.post("/orders", status_code=201)
def create_order(body: OrderIn, idempotency_key: str = Header(default="", alias=IDEMPOTENCY_HEADER)) -> dict:
    try:
        order_rules.assert_currency(body.currency)
    except ValueError as error:
        raise HTTPException(status_code=400, detail=str(error))

    if not idempotency_key:
        # 未携带请求标识：保持原有处理方式
        try:
            orders.insert(body.tenant, body.order_id, body.amount_cents, body.currency)
        except Exception as error:
            if "UNIQUE" in str(error):
                raise HTTPException(status_code=409, detail="order already accepted")
            raise
        return orders.get(body.tenant, body.order_id)

    try:
        result = orders_uc.accept_order(
            body.tenant, idempotency_key, body.order_id, body.amount_cents, body.currency
        )
    except orders_uc.IdempotentConflict as error:
        raise HTTPException(status_code=422, detail=str(error))
    if result.status_code != 201:
        raise HTTPException(status_code=result.status_code, detail=result.body.get("detail"))
    return result.body

@app.post("/orders/import")
def import_orders(body: str = Body(default="", media_type="text/plain")) -> dict:
    # 逗号分隔文本按行受理：部分成功、逐行结论、可安全重试；不携带请求标识
    return batch_uc.import_orders(body)

@app.get("/orders/{order_id}")
def read_order(order_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = x_tenant or ""
    if not tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    order = orders.get(tenant, order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/orders/{order_id}/payments")
def add_payment(
    order_id: str,
    body: PaymentIn,
    x_tenant: str = Header(default=""),
    idempotency_key: str = Header(default="", alias=IDEMPOTENCY_HEADER),
) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")

    if not idempotency_key:
        # 未携带请求标识：保持原有处理方式
        try:
            order = orders.add_payment(x_tenant, order_id, body.amount_cents)
        except ValueError as error:
            raise HTTPException(status_code=409, detail=str(error))
        if order is None:
            raise HTTPException(status_code=404, detail="order not found")
        return order

    try:
        result = orders_uc.register_payment(x_tenant, idempotency_key, order_id, body.amount_cents)
    except orders_uc.IdempotentConflict as error:
        raise HTTPException(status_code=422, detail=str(error))
    if result.status_code != 200:
        raise HTTPException(status_code=result.status_code, detail=result.body.get("detail"))
    return result.body

@app.post("/orders/{order_id}/reversals")
def add_reversal(
    order_id: str,
    body: ReversalIn,
    x_tenant: str = Header(default=""),
    idempotency_key: str = Header(default="", alias=IDEMPOTENCY_HEADER),
) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")

    if not idempotency_key:
        # 未携带请求标识：与收款一致的原有处理方式
        try:
            order = orders.reverse_payment(x_tenant, order_id, body.amount_cents)
        except ValueError as error:
            raise HTTPException(status_code=409, detail=str(error))
        if order is None:
            raise HTTPException(status_code=404, detail="order not found")
        return order

    try:
        result = orders_uc.reverse_payment(x_tenant, idempotency_key, order_id, body.amount_cents)
    except orders_uc.IdempotentConflict as error:
        raise HTTPException(status_code=422, detail=str(error))
    if result.status_code != 200:
        raise HTTPException(status_code=result.status_code, detail=result.body.get("detail"))
    return result.body

@app.get("/orders/{order_id}/reversals")
def read_reversals(order_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = x_tenant or ""
    if not tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    records = orders.list_reversals(tenant, order_id)
    if records is None:
        # 跨租户同样按不存在处理，不泄漏订单是否存在
        raise HTTPException(status_code=404, detail="order not found")
    return {"order_id": order_id, "reversals": records}

@app.post("/orders/{order_id}/reconciliations")
def add_reconciliation(
    order_id: str,
    body: ReconcileIn,
    x_tenant: str = Header(default=""),
    idempotency_key: str = Header(default="", alias=IDEMPOTENCY_HEADER),
) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")

    if not idempotency_key:
        # 未携带请求标识：与收款、冲正一致的原有处理方式
        try:
            order = orders.reconcile(x_tenant, order_id, body.amount_cents)
        except ValueError as error:
            raise HTTPException(status_code=409, detail=str(error))
        if order is None:
            raise HTTPException(status_code=404, detail="order not found")
        return order

    try:
        result = orders_uc.reconcile_order(x_tenant, idempotency_key, order_id, body.amount_cents)
    except orders_uc.IdempotentConflict as error:
        raise HTTPException(status_code=422, detail=str(error))
    if result.status_code != 200:
        raise HTTPException(status_code=result.status_code, detail=result.body.get("detail"))
    return result.body

@app.get("/orders/{order_id}/reconciliations")
def read_reconciliations(order_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = x_tenant or ""
    if not tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    records = orders.list_reconciliations(tenant, order_id)
    if records is None:
        # 跨租户同样按不存在处理，不泄漏订单是否存在
        raise HTTPException(status_code=404, detail="order not found")
    return {"order_id": order_id, "reconciliations": records}

@app.post("/orders/{order_id}/correction")
def correct_order(
    order_id: str,
    body: CorrectionIn,
    x_tenant: str = Header(default=""),
    idempotency_key: str = Header(default="", alias=IDEMPOTENCY_HEADER),
) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")

    if not idempotency_key:
        # 未携带请求标识：与收款、冲正、核销一致的处理方式
        try:
            order = orders.correct(
                x_tenant, order_id, body.order_id, body.amount_cents, body.currency
            )
        except ValueError as error:
            raise HTTPException(status_code=409, detail=str(error))
        if order is None:
            raise HTTPException(status_code=404, detail="order not found")
        return order

    try:
        result = orders_uc.correct_order(
            x_tenant, idempotency_key, order_id, body.order_id, body.amount_cents, body.currency
        )
    except orders_uc.IdempotentConflict as error:
        raise HTTPException(status_code=422, detail=str(error))
    if result.status_code != 200:
        raise HTTPException(status_code=result.status_code, detail=result.body.get("detail"))
    return result.body

@app.get("/orders/{order_id}/corrections")
def read_corrections(order_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = x_tenant or ""
    if not tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    records = orders.list_corrections(tenant, order_id)
    if records is None:
        # 跨租户同样按不存在处理，不泄漏订单是否存在
        raise HTTPException(status_code=404, detail="order not found")
    return {"order_id": order_id, "corrections": records}

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--migrate", action="store_true")
    args = parser.parse_args()
    migrate()
    if args.migrate:
        print("migrated")
        return
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=args.port)

if __name__ == "__main__":
    main()

ALLOWED_CURRENCIES = {"CNY", "USD", "EUR", "JPY"}

def assert_currency(currency: str) -> None:
    if currency not in ALLOWED_CURRENCIES:
        raise ValueError("unsupported currency")

import os
import tempfile
from concurrent.futures import ThreadPoolExecutor

_tmp_dir = tempfile.mkdtemp()
os.environ.setdefault("APP_DB", os.path.join(_tmp_dir, "corrections.sqlite"))

from fastapi.testclient import TestClient

from app.entry import app
from app.store.db import migrate

migrate()
client = TestClient(app)

TENANT = "tcor"


def _accept(order_id: str, amount: int = 1000, currency: str = "CNY", tenant: str = TENANT, key: str | None = None):
    headers = {"Idempotency-Key": key} if key else {}
    return client.post(
        "/orders",
        json={"tenant": tenant, "order_id": order_id, "amount_cents": amount, "currency": currency},
        headers=headers,
    )


def _correct(order_id: str, new_id: str, amount: int, currency: str, key: str | None = None, tenant: str = TENANT):
    headers = {"X-Tenant": tenant}
    if key:
        headers["Idempotency-Key"] = key
    return client.post(
        f"/orders/{order_id}/correction",
        json={"order_id": new_id, "amount_cents": amount, "currency": currency},
        headers=headers,
    )


def _corrections(order_id: str, tenant: str = TENANT):
    return client.get(f"/orders/{order_id}/corrections", headers={"X-Tenant": tenant})


def _get(order_id: str, tenant: str = TENANT):
    return client.get(f"/orders/{order_id}", headers={"X-Tenant": tenant})


def _pay(order_id: str, amount: int, key: str | None = None, tenant: str = TENANT):
    headers = {"X-Tenant": tenant}
    if key:
        headers["Idempotency-Key"] = key
    return client.post(f"/orders/{order_id}/payments", json={"amount_cents": amount}, headers=headers)


def _reverse(order_id: str, amount: int, key: str | None = None, tenant: str = TENANT):
    headers = {"X-Tenant": tenant}
    if key:
        headers["Idempotency-Key"] = key
    return client.post(f"/orders/{order_id}/reversals", json={"amount_cents": amount}, headers=headers)


def _reconcile(order_id: str, amount: int, key: str | None = None, tenant: str = TENANT):
    headers = {"X-Tenant": tenant}
    if key:
        headers["Idempotency-Key"] = key
    return client.post(f"/orders/{order_id}/reconciliations", json={"amount_cents": amount}, headers=headers)


def test_correction_changes_content_and_order_becomes_readable_by_new_id() -> None:
    _accept("c1", 500, "CNY")
    resp = _correct("c1", "c1-new", 800, "USD")
    assert resp.status_code == 200
    body = resp.json()
    assert body["order_id"] == "c1-new"
    assert body["amount_cents"] == 800 and body["currency"] == "USD"
    # 尚未发生收款：已收/未收按新金额闭合
    assert body["paid_cents"] == 0 and body["outstanding_cents"] == 800
    assert body["status"] == "accepted"

    # 按新标识可读，按旧标识不再存在
    assert _get("c1-new").status_code == 200
    assert _get("c1").status_code == 404


def test_correction_can_keep_order_id_and_only_change_content() -> None:
    _accept("c2", 500, "CNY")
    resp = _correct("c2", "c2", 640, "EUR")
    assert resp.status_code == 200
    got = _get("c2").json()
    assert got["amount_cents"] == 640 and got["currency"] == "EUR"
    assert got["outstanding_cents"] == 640


def test_order_with_payment_cannot_be_corrected() -> None:
    _accept("c3", 500)
    _pay("c3", 200)
    resp = _correct("c3", "c3-x", 999, "USD")
    assert resp.status_code == 409
    assert "cannot be corrected" in resp.json()["detail"]

    # 金额、币种、标识、状态与留痕保持不变
    got = _get("c3").json()
    assert got["amount_cents"] == 500 and got["currency"] == "CNY"
    assert got["paid_cents"] == 200 and got["status"] == "accepted"
    assert _get("c3-x").status_code == 404


def test_order_with_reversal_trace_even_after_paid_back_to_zero_cannot_be_corrected() -> None:
    _accept("c4", 500)
    _pay("c4", 200)
    _reverse("c4", 200)  # paid_cents 回到 0，但存在收款与冲正留痕
    got = _get("c4").json()
    assert got["paid_cents"] == 0

    resp = _correct("c4", "c4-x", 100, "CNY")
    assert resp.status_code == 409
    assert "cannot be corrected" in resp.json()["detail"]
    assert _get("c4").json()["amount_cents"] == 500


